<?php
namespace Tests\Feature;
use App\Models\Book; use App\Models\Cart; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class GuestCheckoutIntegrationTest extends TestCase { use RefreshDatabase; public function test_guest_checkout_creates_order_snapshot_and_reduces_stock(): void { $book=Book::factory()->create(['price'=>50000,'stock'=>5]); $token='11111111-1111-4111-8111-111111111111'; $cart=Cart::create(['guest_token'=>$token]); $cart->items()->create(['book_id'=>$book->id,'quantity'=>2]); $this->postJson('/api/checkout',['address'=>['recipient_name'=>'Tamu','phone'=>'08123456789','address_line_1'=>'Jl. Buku','city'=>'Jakarta','province'=>'DKI Jakarta','postal_code'=>'10110']],['X-Cart-Token'=>$token])->assertCreated()->assertJsonPath('data.status','pending_payment'); $this->assertDatabaseHas('order_items',['book_id'=>$book->id,'quantity'=>2,'unit_price'=>50000]); $this->assertDatabaseHas('stock_movements',['book_id'=>$book->id,'type'=>'sale','quantity'=>-2]); $this->assertDatabaseHas('books',['id'=>$book->id,'stock'=>3]); $this->assertDatabaseCount('cart_items',0); } }
